  /* ---------- daily world: debris, forage, artifact spots ---------- */
  function seedDebris(n){ for(let i=0;i<n;i++){ const x=ri(-13,13), z=ri(-5,13), k=G.tkey(x,z); if(S.debris.has(k)||G.getTile(x,z)) continue; if(Math.abs(x)<=2&&z<=13) continue; const r=Math.random(), t=r<.5?'weed':r<.74?'stone':r<.93?'twig':'stump'; S.debris.set(k,{t,hp:t==='stump'?4:t==='boulder'?6:1,x,z}); } G.rebuildDebris(); }
