  /* ---------- the day turns over ---------- */
  G.endDay=function(passedOut){
    if(S.inMine) G.mine.leave(true); if(S.boating){ S.boating=false; }
    if(G.mine.mode==='desert'&&G.leaveDesert) G.leaveDesert();
    const lines=[]; let earned=0; for(const [k,i,n,p] of S.shipped){ const v=n*p; earned+=v; lines.push(META.of(k,i).name+' ×'+n+' = '+v+'g'); } S.shipped=[]; S.gold+=earned; S.stats.earned+=earned;
    if(passedOut){ const fee=Math.min(1000,Math.floor(S.gold*.1)); S.gold-=fee; lines.push('💊 '+L('昏倒了,被送回家,扣除 ','You passed out and were carried home. Cost ')+fee+'g'); }
    const energy=passedOut?S.maxEnergy*.5:(S.time>1440?S.maxEnergy*(1-(S.time-1440)/240):S.maxEnergy);
    growth();
    S.day++; S.absDay++; if(S.day>SEASON_DAYS){ S.day=1; S.season=(S.season+1)%4; if(S.season===0) S.year++; }
    S.time=360; S.energy=Math.round(energy); S.hp=S.maxHp; S.weather=S.tomorrow; rollTomorrow(); S.luck=rnd(-.1,.1); S.festDone=false;
    if(S.weather==='rain'||S.weather==='storm') for(const [k,tl] of S.tiles) if(tl.tilled&&!inGreenhouse(...k.split(',').map(Number))){ tl.watered=true; if(tl.crop) tl.crop.watered=true; }
    for(const [k,tl] of S.tiles){ if(tl.sprinkler){ const [x,z]=k.split(',').map(Number), r=tl.sprinkler; const cells=r===1?[[1,0],[-1,0],[0,1],[0,-1]]:(()=>{ const o=[]; for(let a=-r+1;a<=r-1;a++) for(let b=-r+1;b<=r-1;b++) if(a||b) o.push([a,b]); return o; })(); for(const [dx,dz] of cells){ const t2=G.getTile(x+dx,z+dz); if(t2&&t2.tilled){ t2.watered=true; if(t2.crop) t2.crop.watered=true; } } } }
    for(const k of S.tiles.keys()){ const [x,z]=k.split(',').map(Number); G.refreshTileMesh(x,z); G.rebuildCrop(x,z); }
    for(const m of S.machines){ const tr=CRAFTABLES[m.id].tree; if(m.id==='worm_bin') m.stock=(m.stock||0)+ri(2,5); if(m.id==='lightning_rod'&&S.weather==='storm'&&Math.random()<.5&&!m.stock) m.stock=1; if(m.id==='solar_panel'&&S.weather==='clear'&&(m.age=(m.age||0)+1)>=7){ m.age=0; m.stock=(m.stock||0)+1; } if(!tr) continue; m.age=(m.age||0)+1; if(m.age>=28&&S.season===FRUIT[tr].season) m.stock=Math.min(3,(m.stock||0)+1); }
    animalsDay(); crabsDay(); orders(); spawnForage(); spawnDigs(); if(S.debris.size<90&&S.absDay%1===0) seedDebris(2);
    S.felled=S.felled.filter(([i,d])=>{ if(S.absDay>=d){ restoreWorld('tree',i); return false; } return true; }); S.broken=S.broken.filter(([i,d])=>{ if(S.absDay>=d){ restoreWorld('rock',i); return false; } return true; });
    S.can=canCapacity(); NPCS.forEach(n=>{ const f=fr(n.id); if(f.talk<S.absDay&&f.pts>0) f.pts=Math.max(0,f.pts-(S.spouse===n.id?20:f.dating?8:2)); }); S.buffs=[]; G.renderBuffs&&G.renderBuffs();
    festivalsToday(); dailyMail(); G.sysDay&&G.sysDay(); S.sub=false; if(S.engaged&&S.absDay>=S.weddingDay){ S.spouse=S.engaged; S.engaged=null; S.pendingMsg.push({text:L('婚礼在广场举行,全镇都来了。今后你们一起住在小屋里。','The wedding is held in the plaza with the whole town there. From now on you share the cabin.')}); }
    if(S.spouse&&Math.random()<.3){ const b=['coffee','bread','fried_egg']; G.give('food',pick(b),1,true); S.pendingMsg.push({text:L('爱人给你做了早饭。','Your spouse made you breakfast.')}); }
    G.onNewDay&&G.onNewDay(); G.saveGame(); questTick();
    return {lines,earned}; };
  function growth(){ for(const [k,tl] of S.tiles){ const [x,z]=k.split(',').map(Number), gh=inGreenhouse(x,z); if(tl.crop){ const c=CROPS[tl.crop.id]; const next=(S.day===SEASON_DAYS)?(S.season+1)%4:S.season; if(!gh&&!c.season.includes(next)){ tl.crop=null; continue; }
        if(tl.watered){ tl.crop.fresh=false; const fast=(tl.fert==='s1'?.1:tl.fert==='s2'?.25:0)+(S.prof.agriculturist?.1:0); tl.crop.acc=(tl.crop.acc||0)+1/(1-fast); const sp=Math.floor(tl.crop.acc); tl.crop.acc-=sp; if(tl.crop.cool){ if(--tl.crop.regrowing<=0){ tl.crop.cool=false; tl.crop.stage=c.days; } } else if(tl.crop.stage<c.days) tl.crop.stage=Math.min(c.days,tl.crop.stage+sp); } }
      if(!tl.crop&&!tl.watered&&!tl.sprinkler&&Math.random()<.1) { tl.tilled=false; tl.fert=null; } const keep=tl.fert==='r1'?.33:tl.fert==='r2'?.66:0; if(keep&&tl.watered&&Math.random()<keep) continue; tl.watered=false; if(tl.crop) tl.crop.watered=false; }
    // crows take a crop when too many stand unguarded
    const crops=[...S.tiles.entries()].filter(([k,t])=>t.crop&&!inGreenhouse(...k.split(',').map(Number))); if(crops.length>=15&&Math.random()<.5){ const [k,t]=pick(crops), [x,z]=k.split(',').map(Number), guarded=S.placements.some(p=>p.id==='scarecrow'&&Math.hypot(p.x-x,p.z-z)<=8); if(!guarded){ t.crop=null; S.pendingMsg.push({text:L('乌鸦吃掉了一株作物。立个稻草人吧。','A crow ate one of your crops. Try a scarecrow.')}); } } }
  function orders(){ S.orders=S.orders.filter(o=>{ if(S.absDay>=o.day){ const B=BUILDINGS[o.id]; if(B.up) S.built[B.up]=B.lv; else S.built[o.id]=(S.built[o.id]||0)+1; G.onBuilt&&G.onBuilt(B.up||o.id); S.pendingMsg.push({text:name(BUILDINGS[o.id].nm)+L(' 完工了!',' is finished!')}); return false; } return true; }); if(S.toolAway&&S.absDay>=S.toolAway.day) S.pendingMsg.push({text:L('工具升级好了,去铁匠铺取。','Your tool is ready at the blacksmith.')}); }
  /* friendship 0-1000, mood from being fed, petted and warm. Quality and big or rare products follow them */
  function animalsDay(){ const clear=S.season!==3&&S.weather==='clear'; for(const a of S.animals){ const def=ANIMALS[a.type], indoor=!clear, fed=!indoor||S.hay>0; if(indoor&&S.hay>0) S.hay--; const fast=(def.house==='coop'&&S.prof.coopmaster)||(def.house==='barn'&&S.prof.shepherd); a.fr=clamp((a.fr||0)+(a.petted?(fast?15:0):-10)+(fed?5:-20),0,1000); a.mood=fed?1:0; a.petted=false; a.age=(a.age||0)+1; const every=a.type==='sheep'&&S.prof.shepherd?2:a.type==='rabbit'&&S.prof.shepherd?3:def.days; if(!fed||a.age<3||a.age%every!==0) continue; if(def.dig&&S.season===3) continue; const luck=S.luck+buffOf('luck')*.02, big=def.big&&a.fr>=200&&Math.random()<(a.fr+a.fr*.5)/1250+luck, rare=def.rare&&a.fr>=200&&Math.random()<(a.fr+a.fr*.5)/5000+luck, id=rare?def.rare:big?def.big:def.prod, k=(a.fr+(S.prof[def.house==='coop'?'coopmaster':'shepherd']?200:0))/1000+luck, r=Math.random(), q=k>=.9&&r<k/4?3:r<k/2?2:r<k?1:0; S.coop[id+(q?'~'+q:'')]=(S.coop[id+(q?'~'+q:'')]||0)+1; } }
  G.petAnimal=()=>{ for(const a of S.animals){ const m=a.ref; if(m&&Math.hypot(m.A.x-player.pos.x,m.A.z-player.pos.z)<2.2&&!a.petted){ a.petted=true; a.fr=clamp((a.fr||0)+15,0,1000); toast('❤ '+name(ANIMALS[a.type].nm)); xp('farm',2); m.wait=1.5; return true; } } return false; };
  G.openCoopMenu=()=>modal(L('🐔 动物','🐔 Animals'),body=>{ body.appendChild(el('div','hint','🌾 '+S.hay+' · '+L('靠近动物按 E 抚摸','Press E by an animal to pet it'))); const g=el('div','grid'); body.appendChild(g); const keys=Object.keys(S.coop).filter(k=>S.coop[k]>0); const c=el('div','buy'+(keys.length?'':' dim')); c.innerHTML='<div class="em">🧺</div><div class="nm">'+L('收取产物','Collect')+'</div><div class="pr">'+keys.map(k=>META.of('product',k).em+S.coop[k]).join(' ')+'</div>'; c.onclick=()=>{ let got=0, miss=null; for(const k of keys){ const b=split(k)[0], tool=/milk/.test(b)?'pail':b==='wool'&&S.animals.some(a=>a.type==='sheep')&&!S.animals.some(a=>a.type==='rabbit')?'shears':null; if(tool&&!S.tools[tool]){ miss=tool; continue; } if(G.give('product',k,S.coop[k],true)){ got+=S.coop[k]; delete S.coop[k]; } } if(miss) toast(miss==='pail'?L('挤奶要先买挤奶桶','Buy a milk pail to milk them'):L('剪毛要先买剪刀','Buy shears to shear them')); xp('farm',5*got); G.openCoopMenu(); }; g.appendChild(c); S.animals.forEach(a=>{ const d=ANIMALS[a.type]; g.appendChild(el('div','buy','<div class="em">'+d.em+'</div><div class="nm">'+name(d.nm)+'</div><div class="pr">❤'+Math.round((a.fr||0)/200)+'/5 '+(a.mood?'😊':'😐')+'</div>')); }); });
  function crabsDay(){ for(const c of S.crabs){ if(c.out||(!S.prof.luremaster&&!G.invTake('mat','bait',1))) continue; const pool=Object.keys(FISH).filter(k=>FISH[k].pot===(c.sea?'sea':'fresh')), junk=['trash','driftwood','cola_can','soggy_paper','broken_cd','broken_glasses']; c.out=!S.prof.mariner&&Math.random()<.2?'trash:'+pick(junk):'fish:'+pick(pool); } }
