  function dailyMail(){ if(S.absDay===1) mailTo('亲爱的新邻居:\n欢迎来到星星露谷。这是一点小心意。——镇长 里奥','Dear new neighbour:\nWelcome to StarVale. A little something to start you off. — Mayor Leo',['seed','parsnip',5]); if(S.day===1&&S.absDay>1) mailTo('新的季节开始了,别忘了更换当季种子。——小梅','A new season. Remember to change your seeds. — Mei'); const f=FESTIVALS.find(x=>x.s===S.season&&x.d===S.day+1); if(f) mailTo('明天是'+f.nm.zh+'!到广场来吧。'+f.nm.zh+':'+f.desc.zh,'Tomorrow is the '+f.nm.en+'! Come to the plaza. '+f.desc.en); const b=NPCS.find(n=>n.bday[0]===S.season&&n.bday[1]===S.day); if(b) S.pendingMsg.push({text:L('今天是 ','Today is ')+name(b.nm)+L(' 的生日',"'s birthday")}); if(S.mail.length) toast('✉️ '+L('有新邮件,去信箱看看','You have mail')); }
