  function nodeDrop(n){ const k=n.kind, extra=S.prof.miner?1:0, f=S.mineLevel; G.give('mat','stone',1,true); if(k==='copper'||k==='iron'||k==='gold_ore'||k==='iridium') G.give('ore',k,ri(1,3)+extra); if(k==='coal') G.give('ore','coal',ri(1,2)*(S.prof.prospector?2:1)); if(k==='gem'){ const pool=f<40?['earth_crystal','amethyst','topaz','quartz']:f<80?['frozen_tear','aquamarine','jade','quartz']:['fire_quartz','ruby','emerald','diamond'], i=pick(pool); G.give('gem',i,S.prof.geologist&&Math.random()<.5?2:1); } if(k==='geode'){ const g=f<40?'geode':f<80?'frozen_geode':'magma_geode'; G.give('mat',g,S.prof.excavator&&Math.random()<.5?2:1); } if(k==='stone'&&Math.random()<.015) G.give('mat',pick(['geode','frozen_geode','magma_geode']),1); if(k==='stone'&&Math.random()<.008+f*.00002) G.give('forage',pick(['cave_carrot','purple_mushroom']),1); if(M.cavern&&k==='stone'&&Math.random()<.004) G.give('ore','radioactive',1); }
