  /* ---------- saves ---------- */
  const SAVE_KEYS=['season','day','year','time','gold','energy','maxEnergy','hp','maxHp','toolLvl','weapon','rod','can','inv','weather','tomorrow','luck','mineMax','xp','prof','bag','hay','built','orders','mail','quests','stats','absDay','museum','cc','ccDone','felled','broken','forage','digs','machines','placements','chests','crabs','friends','spouse','engaged','weddingDay','coop','toolAway','shipped','recipes','tackle','tackleUses','rings','boots','guild','tokens','achieved','mineChests','tools','tapped','owned','year','board','quest','order','cart','millIn','millOut','ponds','hutch','obelisks','krobusDrop','spouseDrop','fairDrop','joja','martBought','panning','pan','giants','baby','children','quarryDay'];
  G.snapshot=()=>{ const d={v:3}; SAVE_KEYS.forEach(k=>d[k]=S[k]); d.tiles=[...S.tiles.entries()]; d.debris=[...S.debris.entries()]; d.animals=S.animals.map(a=>({type:a.type,fr:a.fr,age:a.age,mood:a.mood})); return d; };
